draw((-3.97,.1)--(-1.97,3.1)^^(3.97,.1)--(1.97,3.1));

[/asy]

doc.solution:
[asy]
import solids; size(150); import three; defaultpen(linewidth(0.5)); currentprojection = orthographic(5,0,2);
revolution c = cone((0,0,0), 8, 12);
revolution c2 = cone((0,0,6), 4, 6);
revolution c3 = cylinder((0,0,6), 4, 0.01);
draw(c,black);
draw(c2,black);

draw((0,8,0)--(0,0,0)--(0,0,12),linewidth(0.8));
draw((0,4,6)--(0,0,6),linewidth(0.8));
